function coinGeo(){ var v=[],ix=[],seg=28,h=0.06,i,a,b0; function vt(x,y,z,nx,ny,nz,u,w){ v.push(x,y,z,nx,ny,nz,u,w); }
  for(var sd=-1;sd<=1;sd+=2){ b0=v.length/8; vt(0,0,sd*h,0,0,sd,0.5,0.5); for(i=0;i<=seg;i++){ a=i/seg*6.2832; vt(Math.cos(a)*0.5,Math.sin(a)*0.5,sd*h,0,0,sd,0.5+Math.cos(a)*0.5,0.5-Math.sin(a)*0.5); }
    for(i=0;i<seg;i++){ if(sd>0) ix.push(b0,b0+1+i,b0+2+i); else ix.push(b0,b0+2+i,b0+1+i); } }
  b0=v.length/8; for(i=0;i<=seg;i++){ a=i/seg*6.2832; vt(Math.cos(a)*0.5,Math.sin(a)*0.5,-h,Math.cos(a),Math.sin(a),0,i/seg,0); vt(Math.cos(a)*0.5,Math.sin(a)*0.5,h,Math.cos(a),Math.sin(a),0,i/seg,1); }
  for(i=0;i<seg;i++){ var k=b0+i*2; ix.push(k,k+2,k+1,k+1,k+2,k+3); }
  // borde levantado (anillo) adelante y atras
  for(sd=-1;sd<=1;sd+=2){ b0=v.length/8; for(i=0;i<=seg;i++){ a=i/seg*6.2832; vt(Math.cos(a)*0.5,Math.sin(a)*0.5,sd*(h+0.025),0,0,sd,0,0); vt(Math.cos(a)*0.4,Math.sin(a)*0.4,sd*(h+0.025),Math.cos(a)*-0.5*sd*0,0,sd,0,0); }
    for(i=0;i<seg;i++){ var k2=b0+i*2; if(sd>0) ix.push(k2,k2+2,k2+1,k2+1,k2+2,k2+3); else ix.push(k2,k2+1,k2+2,k2+1,k2+3,k2+2); } }
  return malla(v,ix); }
