function dibujar(m,tex,modelo,col,em){ var real=REAL&&SHADERS; if(!TX[tex]&&TX.blanco&&tex!=="moneda") tex="blanco"; if(tex==='moneda'&&real){ m=G.moneda||(G.moneda=coinGeo()); tex='oro'; col=col?[1,0.96,0.8,col[3]===undefined?1:col[3]]:[1,0.96,0.8,1]; em=0; }
  if(SPASS){ if(SKIP||(col&&col[3]!==undefined&&col[3]<0.9)||tex==='nube'||tex==='brizna'||(em||0)>=0.9||(SHMAX&&modelo[13]>SHMAX)) return; gl.bindBuffer(gl.ARRAY_BUFFER,m.b); gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER,m.e);
    gl.enableVertexAttribArray(AS.p); gl.vertexAttribPointer(AS.p,3,gl.FLOAT,false,32,0); var alf=tex==='hojaAlfa'||tex==='ramaPino'; gl.uniform1f(US.at,alf?1:0);
    if(AS.uv>=0){ gl.enableVertexAttribArray(AS.uv); gl.vertexAttribPointer(AS.uv,2,gl.FLOAT,false,32,24); } if(alf){ gl.activeTexture(gl.TEXTURE0); gl.bindTexture(gl.TEXTURE_2D,TX[tex]); gl.uniform1i(US.tx,0); } gl.uniformMatrix4fv(US.Mo,false,modelo); gl.drawElements(gl.TRIANGLES,m.n,gl.UNSIGNED_SHORT,0); return; }
  if(U.mt) gl.uniform1f(U.mt,!real?0:(tex==='oro'||tex==='cromo')?1:tex==='hielo'?2:tex==='agua'?3:tex==='brizna'?4:tex==='pintura'?5:0);
  gl.bindBuffer(gl.ARRAY_BUFFER,m.b); gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER,m.e);
  gl.enableVertexAttribArray(A.p); gl.vertexAttribPointer(A.p,3,gl.FLOAT,false,32,0);
  gl.enableVertexAttribArray(A.n); gl.vertexAttribPointer(A.n,3,gl.FLOAT,false,32,12);
  gl.enableVertexAttribArray(A.uv); gl.vertexAttribPointer(A.uv,2,gl.FLOAT,false,32,24);
  gl.activeTexture(gl.TEXTURE0); gl.bindTexture(gl.TEXTURE_2D,TX[tex]||TX.blanco); gl.uniform1i(U.tx,0);
  col=col||[1,1,1,1]; gl.uniform4f(U.C,col[0],col[1],col[2],col[3]===undefined?1:col[3]); gl.uniform1f(U.em,em||0);
  gl.uniformMatrix4fv(U.Mo,false,modelo); gl.drawElements(gl.TRIANGLES,m.n,gl.UNSIGNED_SHORT,0); }
function hexC(h,a){ var n=parseInt(h.slice(1),16); return [((n>>16)&255)/255,((n>>8)&255)/255,(n&255)/255,a===undefined?1:a]; }

// ---------------- personajes (Franco y zombis) ----------------
