// ================= FRANCO HD (como la hoja de personaje) =================
var SKIN_HD=true; try{ SKIN_HD=localStorage.getItem('franco3d-skin')!=='cubos'; }catch(e){}
// superelipsoide: formas redondeadas tipo ropa (e chico = mas cuadrado)
function superGeo(e1,e2,sg,rg){ var v=[],ix=[],i,j; function c_(w,m){ var c=Math.cos(w); return (c<0?-1:1)*Math.pow(Math.abs(c),m); } function s_(w,m){ var s=Math.sin(w); return (s<0?-1:1)*Math.pow(Math.abs(s),m); }
  for(j=0;j<=rg;j++){ var vv=Math.PI/2-j/rg*Math.PI; for(i=0;i<=sg;i++){ var u=i/sg*2*Math.PI;
    var x=c_(vv,e1)*c_(u,e2), y=s_(vv,e1), z=c_(vv,e1)*s_(u,e2), nx=c_(vv,2-e1)*c_(u,2-e2), ny=s_(vv,2-e1), nz=c_(vv,2-e1)*s_(u,2-e2), nl=Math.hypot(nx,ny,nz)||1;
    v.push(x*0.5,y*0.5,z*0.5,nx/nl,ny/nl,nz/nl,i/sg,j/rg); } }
  for(j=0;j<rg;j++) for(i=0;i<sg;i++){ var a=j*(sg+1)+i,b=a+sg+1; ix.push(a,a+1,b,a+1,b+1,b); } return malla(v,ix); }
// mechon de pelo: base redonda y punta finita, un poco curvado
function mechonGeo(curva){ var v=[],ix=[],sg=10,rg=10,i,j; for(j=0;j<=rg;j++){ var t=j/rg, r=t<0.24?0.5*Math.sqrt(Math.max(0,1-Math.pow((0.24-t)/0.24,2))):0.5*Math.pow((1-t)/0.76,0.85), cx=curva*t*t;
    for(i=0;i<=sg;i++){ var a=i/sg*6.2832, c=Math.cos(a), s=Math.sin(a); v.push(cx+c*r,t,s*r,c,0.25,s,i/sg,t); } }
  for(j=0;j<rg;j++) for(i=0;i<sg;i++){ var a2=j*(sg+1)+i,b=a2+sg+1; ix.push(a2,b,a2+1,a2+1,b,b+1); } return malla(v,ix); }
function toroGeo(R,r,sg,rg){ var v=[],ix=[],i,j; for(j=0;j<=rg;j++){ var b=j/rg*6.2832; for(i=0;i<=sg;i++){ var a=i/sg*6.2832, cx=Math.cos(a), cz=Math.sin(a), cb=Math.cos(b), sb=Math.sin(b);
    v.push((R+r*cb)*cx,r*sb,(R+r*cb)*cz,cb*cx,sb,cb*cz,i/sg,j/rg); } }
  for(j=0;j<rg;j++) for(i=0;i<sg;i++){ var a2=j*(sg+1)+i,b2=a2+sg+1; ix.push(a2,a2+1,b2,a2+1,b2+1,b2); } return malla(v,ix); }
function mallasHD(){ if(G.supT) return; G.supT=superGeo(0.55,0.7,24,16); G.supP=superGeo(0.3,0.9,20,14); G.supZ=superGeo(0.45,0.55,20,12); G.supF=superGeo(0.5,0.5,16,10);
  G.mech0=mechonGeo(0); G.mechI=mechonGeo(0.3); G.mechD=mechonGeo(-0.3); G.toro=toroGeo(0.5,0.18,24,10); if(!G.esfHD) G.esfHD=esferaGeo(24,18,1); armarPelo(); }
// matriz desde ejes (para poner cada mechon apuntando a donde va)
function matEjes(p,Y,Z,w,L,th){ var yl=Math.hypot(Y[0],Y[1],Y[2]); Y=[Y[0]/yl,Y[1]/yl,Y[2]/yl]; var d=Z[0]*Y[0]+Z[1]*Y[1]+Z[2]*Y[2]; Z=[Z[0]-d*Y[0],Z[1]-d*Y[1],Z[2]-d*Y[2]]; var zl=Math.hypot(Z[0],Z[1],Z[2])||1; Z=[Z[0]/zl,Z[1]/zl,Z[2]/zl];
  var X=[Y[1]*Z[2]-Y[2]*Z[1],Y[2]*Z[0]-Y[0]*Z[2],Y[0]*Z[1]-Y[1]*Z[0]]; return new Float32Array([X[0]*w,X[1]*w,X[2]*w,0,Y[0]*L,Y[1]*L,Y[2]*L,0,Z[0]*th,Z[1]*th,Z[2]*th,0,p[0],p[1],p[2],1]); }
var PELO=[];
