  var hy=-99; for(i=0;i<g.P.length;i++){ p=g.P[i]; if(dentroP(p,j.x,j.z,0)&&p.y<=j.y+0.05&&p.y>hy) hy=p.y; } if(hy>-99) sombra(j.x,hy,j.z,0.8);
