    a.t+=dt; var tob=a.t>0.12?Math.min(1,(a.t-0.12)*3):0; a.x=a.dir*tob*1.7; a.y=(!a.dir&&!a.alto&&!jug)?0:(a.alto||a.dir===0?0.6:0.35)*Math.sin(tob*Math.PI*0.9);
    if(!b.listo){ b.vy-=9.8*dt; b.x+=b.vx*dt; b.y+=b.vy*dt; b.z+=b.vz*dt; if(b.y<0.22){ b.y=0.22; b.vy=-b.vy*0.5; b.vx*=0.8; b.vz*=0.8; }
      var ax_=a.x, ay_=a.y+1, az_=jug?PN_ARCO+0.5:PN_ARCO+0.5;
      if(Math.abs(b.z-az_)<0.6&&Math.abs(b.x-ax_)<(a.dir?0.95:0.6)&&b.y<ay_+1.1&&b.y>ay_-1.1&&!b.salvo){ b.salvo=true; b.vz=-b.vz*0.4+3; b.vx+=(b.x-ax_)*3; b.vy=3; }
      if(b.z<PN_ARCO&&!b.res){ var dentro=Math.abs(b.x)<PN_ANCHO/2-0.1&&b.y<PN_ALTO-0.1&&!b.salvo; b.res=dentro?'gol':(b.salvo?'atajo':'afuera'); if(dentro){ b.vz*=0.15; b.vx*=0.2; } }
      if(b.z<PN_ARCO-1.2){ b.z=PN_ARCO-1.2; b.vz=0; b.vx*=0.5; } }
