function hudPenales(g){ if(!g||g.nombre!=='penales'){ if(hudPenales.el) hudPenales.el.style.display='none'; return; }
  if(!hudPenales.el){ hudPenales.el=el('div','position:absolute;left:50%;bottom:12%;transform:translateX(-50%);width:220px;height:18px;border:3px solid #000;background:#222;display:none;pointer-events:none'); hudPenales.el.innerHTML='<div style="height:100%;width:0;background:linear-gradient(90deg,#40d040,#f0e020 70%,#e02020)"></div>'; hud.appendChild(hudPenales.el); }
  var e=hudPenales.el; e.style.display=g.fase==='apunta'&&!g.fin?'block':'none'; e.firstChild.style.width=Math.round(g.pot*100)+'%'; }
function pnMarca(arr){ var s=''; for(var i=0;i<Math.max(5,arr.length);i++) s+=i<arr.length?(arr[i]?'<span style="color:#60ff60">●</span>':'<span style="color:#ff5050">✕</span>'):'<span style="color:#888">○</span>'; return s; }

// ---------------- BOLOS 3D ----------------
var BL_LARGO=18;
function blPinos(){ var P=[],f,i; for(f=0;f<4;f++) for(i=0;i<=f;i++) P.push({x:(i-f/2)*0.6,z:-BL_LARGO-f*0.52,cae:0,vx:0,vz:0,rot:0,ry:0,dir:0,fuera:false}); return P; }
function crearBolos(){ var rec=0; try{ rec=+localStorage.getItem('franco3d-bolos')||0; }catch(e){}
  return {nombre:'bolos',cielo:[0.18,0.12,0.25],luz:0.95,t:0,P:blPinos(),cuadro:0,tiro:0,pts:[],tirados:0,fase:'pos',px:0,ang:0,curva:0,bola:null,espera:0,rec:rec,fin:0,total:0,pres:false,
    j:{x:0,y:0,z:1.2,ang:Math.PI,anim:0,mov:0},camDist:5,msg:'A/D: MOVERTE - ESPACIO: APUNTAR Y TIRAR',msgT:4}; }
function blParados(g){ return g.P.filter(function(p){ return !p.cae; }).length; }
function actualizarBolos(g,dt){ g.t+=dt; if(g.msgT>0) g.msgT-=dt; if(g.fin) return; var j=g.j, sp=teclas[' ']||btn.salto, pulso=(sp&&!g.pres)||pulsoEsp; g.pres=sp; pulsoEsp=false;
  yaw+=(0-yaw)*Math.min(1,5*dt); pitch+=(0.3-pitch)*Math.min(1,5*dt);
  if(g.fase==='pos'){ var mv=0; if(teclas.a||teclas.arrowleft) mv-=1; if(teclas.d||teclas.arrowright) mv+=1; if(joy) mv+=joy.dx; g.px=Math.max(-0.75,Math.min(0.75,g.px+mv*dt*1.4)); j.x=g.px; j.mov=Math.abs(mv)>0.1?0.5:0; j.anim+=dt*j.mov*2;
    if(pulso){ g.fase='angulo'; g.t0=g.t; } }
  else if(g.fase==='angulo'){ g.ang=Math.sin((g.t-g.t0)*2.2)*0.045; if(pulso){ g.fase='fuerza'; g.t0=g.t; } }
  else if(g.fase==='fuerza'){ g.fz=0.5+0.5*Math.abs(Math.sin((g.t-g.t0)*2.6)); if(pulso){ g.fase='rueda'; var v=8+g.fz*9; g.bola={x:g.px,z:0.3,vx:Math.sin(g.ang)*v,vz:-Math.cos(g.ang)*v,rot:0,canal:false}; g.espera=0; sonido('salto'); } }
  else if(g.fase==='rueda'){ var b=g.bola; g.espera+=dt; var nsub=Math.ceil(dt/0.008), dts=dt/nsub; for(var sb=0;sb<nsub;sb++){ b.x+=b.vx*dts; b.z+=b.vz*dts; b.rot+=dts*14;
    if(!b.canal&&Math.abs(b.x)>0.95){ b.canal=true; b.x=Math.sign(b.x)*1.18; b.vx=0; sonido('cae'); }
    for(var i=0;i<g.P.length;i++){ var p=g.P[i]; if(p.cae) continue; var d=Math.hypot(p.x-b.x,p.z-b.z); if(!b.canal&&d<0.42){ blTumba(p,(p.x-b.x)/d*4+b.vx*0.3,(p.z-b.z)/d*3+b.vz*0.5); b.vz*=0.93; b.vx+=(b.x-p.x)*0.6; sonido('boom'); } }
    for(i=0;i<g.P.length;i++){ var q=g.P[i]; if(!q.cae||q.cae>0.6) continue; q.vis=q.vis||{}; for(var k=0;k<g.P.length;k++){ var r=g.P[k]; if(r.cae||q.vis[k]) continue; var dd=Math.hypot(r.x-q.x,r.z-q.z); if(dd<0.5){ q.vis[k]=1; if(Math.random()<0.62) blTumba(r,(r.x-q.x)/dd*2.6+q.vx*0.4,(r.z-q.z)/dd*2.2+q.vz*0.4); } } } }
    if(b.z<-BL_LARGO-3||g.espera>4) { g.fase='mira'; g.espera=0; } }
  else if(g.fase==='mira'){ g.espera+=dt; if(g.espera>1.6) blTermina(g); }
  for(i=0;i<g.P.length;i++){ var pp=g.P[i]; if(pp.cae){ pp.cae+=dt; pp.x+=pp.vx*dt; pp.z+=pp.vz*dt; pp.vx*=Math.pow(0.1,dt); pp.vz*=Math.pow(0.1,dt); pp.rot=Math.min(1.5,pp.rot+dt*6); } }
  if(g.bola){ j.x=g.bola.x*0.5; j.z+=(Math.max(-BL_LARGO+3,g.bola.z+3)-j.z)*Math.min(1,dt*3); } else if(g.fase!=='mira'){ j.x=g.px; j.z=1.2; }
}
function blTumba(p,vx,vz){ p.cae=0.001; p.vx=vx; p.vz=vz; p.ry=Math.atan2(vx,vz); }
function blTermina(g){ var base=10-g.P.length, caidos=base+g.P.filter(function(p){ return p.cae; }).length, este=caidos-g.tirados;
  var strike=g.tiro===0&&caidos===10, spare=g.tiro===1&&caidos===10;
  if(strike){ g.msg='STRIKE!!! +20'; g.total+=20; sonido('gano'); } else if(spare){ g.msg='SPARE! +15'; g.total+=15; sonido('gano'); } else { g.msg=este===0?'NINGUNO...':'TIRASTE '+este; g.total+=este; sonido(este?'moneda':'ay'); }
  g.msgT=1.8; g.bola=null;
  if(strike||g.tiro===1){ g.pts.push(strike?'X':spare?'/':''+caidos); g.cuadro++; g.tiro=0; g.tirados=0; g.P=blPinos(); }
  else { g.tiro=1; g.P=g.P.filter(function(p){ return !p.cae; }); g.tirados=caidos; }
  if(g.cuadro>=10){ g.fin=1; var pr=Math.floor(g.total/10), nr=g.total>g.rec; monedas+=pr; if(nr) try{ localStorage.setItem('franco3d-bolos',g.total); }catch(e){} g.msg='FIN! '+g.total+' PUNTOS - +'+pr+' MONEDAS'+(nr?' - RECORD!':'')+' - Q: SALIR'; g.msgT=99; return; }
  g.fase='pos'; }
