  for(i=-4;i<=4;i++) for(var q=0;q<4;q++) dibujar(G.caja,'blanco',M(T(i*3,5.5,-2-q*5),S(0.5,0.08,0.5)),[1,1,0.9,1],1); dibujar(G.caja,'blanco',M(T(0,5.8,-10),S(30,0.1,30)),[0.2,0.15,0.3,1]);
