// ---------------- BASQUET 3D ----------------
var BQ_AROZ=-6, BQ_AROY=3.05, BQ_SPOTS=[[0,-1.5],[-3.5,-3],[3.5,-3],[-5.5,0.3],[5.5,0.3],[0,1.2],[-2.5,0.8],[2.5,0.8]];
function crearBasquet(){ var rec=0; try{ rec=+localStorage.getItem('franco3d-basq')||0; }catch(e){}
  var g={nombre:'basquet',cielo:[0.55,0.75,1],t:0,tiempo:60,pts:0,enc:0,tiros:0,racha:0,rec:rec,fin:0,spot:0,aim:0,pot:0,cargando:false,bola:null,espera:0,camDist:4,FX:[],
    j:{x:0,y:0,z:0,ang:Math.PI,anim:0,mov:0},msg:'60 SEGUNDOS! A/D: APUNTAR - MANTENE ESPACIO Y SOLTA PARA TIRAR',msgT:4};
  bqSpot(g,0); return g; }
function bqSpot(g,i){ g.spot=i; var s=BQ_SPOTS[i]; g.px=s[0]; g.pz=s[1]; g.aim=0; g.pot=0; g.cargando=false; g.bola=null; var dx=0-g.px, dz=BQ_AROZ-g.pz; g.dist=Math.hypot(dx,dz); g.base=Math.atan2(dx,dz);
  // la camara mira al aro desde atras del jugador
  g.j.x=g.px-Math.sin(g.base)*0.8+Math.cos(g.base)*0.75; g.j.z=g.pz-Math.cos(g.base)*0.8-Math.sin(g.base)*0.75; g.j.y=0.3; }
function bqPerfecta(g){ return 0.62+Math.min(1,(g.dist-3)/5)*0.3; }
function actualizarBasquet(g,dt){ g.t+=dt; if(g.msgT>0) g.msgT-=dt; var j=g.j, i;
  for(i=g.FX.length-1;i>=0;i--){ g.FX[i].t+=dt; if(g.FX[i].t>1) g.FX.splice(i,1); }
  if(g.fin) return;
  g.tiempo-=dt; if(g.tiempo<=0&&!g.bola){ g.fin=1; var pr=Math.floor(g.pts/3), nr=g.pts>g.rec; monedas+=pr; if(nr) try{ localStorage.setItem('franco3d-basq',g.pts); }catch(e){} g.msg='SE TERMINO! '+g.pts+' PUNTOS ('+g.enc+'/'+g.tiros+') - +'+pr+' MONEDAS'+(nr?' - RECORD!':'')+' - Q: SALIR'; g.msgT=99; sonido('gano'); return; }
  var ty=g.base+Math.PI; yaw+=(ty-yaw)*Math.min(1,6*dt); pitch+=(0.18-pitch)*Math.min(1,6*dt);
  var sp=teclas[' ']||btn.salto;
  if(!g.bola){ var mv=0; if(teclas.a||teclas.arrowleft) mv-=1; if(teclas.d||teclas.arrowright) mv+=1; if(joy) mv+=joy.dx; g.aim=Math.max(-0.25,Math.min(0.25,g.aim+mv*dt*0.35));
    if(sp){ g.cargando=true; g.pot=Math.min(1,g.pot+dt*0.75); }
    else if(g.cargando){ g.cargando=false; g.tiros++; var per=bqPerfecta(g), err=(g.pot-per), d=g.dist*(1+err*0.9), ang=g.base-g.aim, T_=0.95+d*0.06;
      var sx=g.px+Math.sin(g.base)*0.3, sz=g.pz+Math.cos(g.base)*0.3, sy=2.1, tx=sx+Math.sin(ang)*(d-0.3), tz=sz+Math.cos(ang)*(d-0.3);
      g.bola={x:sx,y:sy,z:sz,vx:(tx-sx)/T_,vz:(tz-sz)/T_,vy:(BQ_AROY-sy+0.5*9.8*T_*T_)/T_,t:0,res:null,rebote:0}; g.espera=0; sonido('salto'); } }
  else { var b=g.bola, n=4, h=dt/n; b.t+=dt;
    for(var k=0;k<n;k++){ var py=b.y; b.vy-=9.8*h; b.x+=b.vx*h; b.y+=b.vy*h; b.z+=b.vz*h;
      // tablero
      if(b.z<BQ_AROZ-0.38&&b.z>BQ_AROZ-0.6&&Math.abs(b.x)<0.9&&b.y>2.9&&b.y<4.0&&b.vz<0){ b.vz=-b.vz*0.6; b.z=BQ_AROZ-0.38; sonido('boom'); }
      var dr=Math.hypot(b.x,b.z-BQ_AROZ);
      if(!b.res&&py>=BQ_AROY&&b.y<BQ_AROY&&dr<0.2){ b.res='enc'; b.vx*=0.2; b.vz*=0.2; }
      else if(!b.res&&Math.abs(b.y-BQ_AROY)<0.13&&dr>0.18&&dr<0.36&&b.rebote<3){ var nx=b.x/dr, nz=(b.z-BQ_AROZ)/dr, vn=b.vx*nx+b.vz*nz; if(vn<0){ b.vx-=1.6*vn*nx; b.vz-=1.6*vn*nz; b.vy=Math.abs(b.vy)*0.45; b.rebote++; sonido('boom'); } }
      if(b.y<0.22){ b.y=0.22; b.vy=-b.vy*0.6; b.vx*=0.8; b.vz*=0.8; } }
    if(b.res==='enc'&&!b.contado){ b.contado=true; var tres=g.dist>6.75, p=(tres?3:2)+(b.rebote?0:(g.racha>=2?1:0)); g.pts+=p; g.enc++; g.racha++; g.msg=(b.rebote?'ADENTRO!':'LIMPIO!! ')+' +'+p+(g.racha>=3?' - RACHA x'+g.racha+'!':''); g.msgT=1.4; sonido('gano'); g.FX.push({t:0}); }
    if(b.t>2.2){ if(!b.contado){ g.racha=0; g.msg=['CASI!','UYYY!','AFUERA...'][(Math.random()*3)|0]; g.msgT=1; sonido('ay'); } var ns=b.contado?(g.spot+1+((Math.random()*(BQ_SPOTS.length-1))|0))%BQ_SPOTS.length:g.spot; bqSpot(g,ns); } }
}
