    var o=AC.createOscillator(), go=AC.createGain(); o.type='sine'; o.frequency.setValueAtTime(70+Math.random()*12,t); o.frequency.exponentialRampToValueAtTime(40,t+0.15); go.gain.setValueAtTime(0.0001,t); go.gain.exponentialRampToValueAtTime(0.12,t+0.008); go.gain.exponentialRampToValueAtTime(0.0001,t+0.22);
    var dry=AC.createGain(); dry.gain.value=0.55; src.connect(f); f.connect(g); o.connect(go); g.connect(dry); go.connect(dry); dry.connect(AC.destination); g.connect(pasoEco.cv); go.connect(pasoEco.cv);
