function rbTMgana(L){ return 6*Math.pow(2.3,L-1); } function rbTMprecio(L){ return Math.round(150*Math.pow(2.55,L-1)); }
function rbVelDe(sp){ return 4+Math.log(Math.max(10,sp))/Math.LN10*2.7; }
function rbMunZ(k){ return RB_Z0-k*RB_ZL-RB_ZL/2; }
function rbMunDe(z){ if(z>RB_Z0) return -1; return Math.min(RB_MUN.length-1,Math.floor((RB_Z0-z)/RB_ZL)); }
