var svHud=null;
function hudSalva(g){ if(!svHud){ svHud=el('div','position:absolute;inset:0;pointer-events:none;display:none');
    svHud.innerHTML='<div style="position:absolute;left:50%;top:10px;transform:translateX(-50%);text-align:center"><div id="svN" style="font-size:13px;color:#ffd040;text-shadow:2px 2px 0 #000"></div><div style="margin-top:6px;width:260px;max-width:60vw;height:18px;border:3px solid #000;background:#333;border-radius:6px;overflow:hidden"><div id="svT" style="height:100%;background:linear-gradient(90deg,#ffb020,#ffe060)"></div></div><div style="font-size:8px;margin-top:3px;text-shadow:1px 1px 0 #000">✏️ LAPIZ</div></div>'+
      '<div id="svC" style="position:absolute;left:50%;top:30%;transform:translateX(-50%);font-size:54px;color:#fff;text-shadow:4px 4px 0 #000"></div>'+
      '<div id="svF" style="position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);display:none;text-align:center;background:rgba(20,30,70,0.9);border:6px solid #ffd040;border-radius:18px;padding:28px 34px;min-width:min(620px,90vw);pointer-events:auto"><div id="svFt" style="font-size:14px;line-height:1.6;margin-bottom:10px"></div><div id="svFe" style="font-size:64px;color:#ffd040;margin-bottom:10px"></div><button id="svO" style="'+BOT+';background:#c06020;font-size:16px;padding:16px 22px">OTRA VEZ</button><button id="svS" style="'+BOT+';background:#30a040;font-size:16px;padding:16px 22px">SIGUIENTE</button><button id="svM" style="'+BOT+';background:#506070;font-size:16px;padding:16px 22px">NIVELES</button></div>';
    hud.appendChild(svHud); svHud.querySelector('#svO').onclick=function(){ empezar('salva',juego.nivel); }; svHud.querySelector('#svS').onclick=function(){ empezar('salva',Math.min(SV_NIV-1,juego.nivel+1)); }; svHud.querySelector('#svM').onclick=function(){ irMenu(); menuSalva(); }; }
  if(!g||g.nombre!=='salva'){ svHud.style.display='none'; return; } svHud.style.display='block';
  svHud.querySelector('#svN').textContent='NIVEL '+(g.nivel+1)+'/'+SV_NIV; svHud.querySelector('#svT').style.width=Math.max(0,100*g.tinta/g.tintaMax)+'%';
  svHud.querySelector('#svC').textContent=g.fase==='juega'&&g.fin===0?Math.ceil(g.cuenta):'';
  var F=svHud.querySelector('#svF'), mostrar=g.fin!==0&&g.finT>0.9; F.style.display=mostrar?'block':'none';
  if(mostrar){ svHud.querySelector('#svFt').innerHTML=g.fin>0?'<span style="color:#60ff60;font-size:44px">GANASTE!</span><br><span style="font-size:14px">FRANCO Y PUGAMER ESTAN A SALVO</span>':'<span style="color:#ff5050;font-size:44px">PERDISTE!</span><br><span style="font-size:14px">'+(g.porGolpe?'TU DIBUJO LE PEGO MUY FUERTE A '+g.hit+'!':'LE PEGARON A '+g.hit+'!')+'</span><br><span style="font-size:11px;color:#cde">PROBA DIBUJAR OTRA COSA</span>'; svHud.querySelector('#svFe').textContent=g.fin>0?'★'.repeat(g.est)+'☆'.repeat(3-g.est):''; svHud.querySelector('#svS').style.display=g.fin>0&&g.nivel<SV_NIV-1?'inline-block':'none'; } }
function menuSalva(){ var nv=0, es={}; try{ nv=+localStorage.getItem('franco3d-salva')||0; es=JSON.parse(localStorage.getItem('franco3d-salvaE')||'{}'); }catch(e){}
  menuEl.style.display='flex'; menuEl.innerHTML=''; menuEl.appendChild(el('div','font-size:18px;color:#ffd040;margin-bottom:6px','SALVA A FRANCO'));
  menuEl.appendChild(el('div','font-size:8px;margin-bottom:8px;line-height:1.8','DIBUJA CON EL MOUSE PARA PROTEGER A FRANCO Y A PUGAMER. EL LAPIZ SE TERMINA!'));
  var gr=el('div','display:grid;grid-template-columns:repeat(10,44px);gap:4px;max-width:96vw;max-height:60vh;overflow:auto');
  var COLS=['#d0a020','#7a9a30','#3a7ab0','#7a4a9a','#b03a3a'];
  for(var i=0;i<SV_NIV;i++){ (function(i){ var abierto_=i<=nv, b=el('button','font:10px "Press Start 2P",monospace;color:#fff;border:3px solid #000;height:44px;padding:0;cursor:'+(abierto_?'pointer':'default')+';background:'+(abierto_?COLS[Math.floor(i/10)]:'#333'),(abierto_?(i+1):'🔒')+'<br><span style="font-size:6px;color:#ffd040">'+(es[i]?'★'.repeat(es[i]):'')+'</span>'); if(abierto_) b.onclick=function(){ empezar('salva',i); }; gr.appendChild(b); })(i); }
  menuEl.appendChild(gr); menuEl.appendChild(el('div','font-size:7px;margin-top:8px;line-height:2;color:#cde','1-10 ABEJAS - 11-20 ROCAS - 21-30 FLECHAS - 31-40 ZOMBIS - 41-50 BOLAS DE FUEGO'));
  var v=el('button',BOT+';background:#c03030;font-size:11px','VOLVER'); v.onclick=mostrarMenu; menuEl.appendChild(v); }

// ---------------- camara y cuadro ----------------
function camSolido(n,x,y,z){ // que cosas no puede atravesar la camara
  if(n==='futauto') return Math.abs(x)>FA_X-0.6||Math.abs(z)>FA_Z-0.6&&!(Math.abs(x)<FA_ARCO-0.5&&y<FA_ALTO-0.5&&Math.abs(z)<FA_Z+5.5)||y>FA_TECHO-0.6||y<0.25;
  if(n==='frankraft') return !!fkB(juego,Math.floor(x),Math.floor(y),Math.floor(z));
  if(n==='almacen') return almSolido(juego,x,y,z);
  if(n==='backrooms') return brSolido(x,y,z);
  if(n==='laberinto'&&y<HW+0.25&&celdaLab(juego,x,z)===1) return true;
  if(n==='parkour'||n==='piso') return false;
  if(n==='parque'&&juego.enBano) return biSolido(x,y,z);
  if(n==='parque') return pqCamSolido(juego,x,y,z);
  if((n==='zombis'||n==='royale')&&juego.O){ for(var i=0;i<juego.O.length;i++){ var o=juego.O[i], e=o.e||1; if(o.t===3){ if(o.w&&Math.abs(x-o.x)<o.w/2+0.15&&Math.abs(z-o.z)<o.d/2+0.15&&y<(o.h||3)) return true; continue; } if(o.rad===undefined) continue; var d=Math.hypot(x-o.x,z-o.z);
      if(o.t===2){ if(d<o.rad+0.2&&y<1.3*e) return true; } else { if(d<o.rad+0.25&&y<4.2*e) return true; if(d<1.5*e&&y>1.9*e&&y<4.6*e) return true; } } }
  return y<0.25; }
