function empezar(n,nivel){ PROY.length=0; HUMO.length=0; modo='juego'; mouseDer=false; pulsoE=false; pulsoEsp=false; clicDer=false; menuEl.style.display='none'; for(var k_ in teclas) delete teclas[k_]; yaw=0; pitch=n==='parkour'?0.5:(n==='laberinto'?0.75:(n==='meteoritos'||n==='piso'?0.6:(n==='almacen'||n==='parque'?0.75:n==='rompe'||n==='mina'||n==='roba'?0.55:n==='pesca'?0.4:n==='bolos'?0.3:n==='penales'?0.22:n==='basquet'?0.18:0.35)));
  SENS=n==='frankraft'?OPFK.sens:1; SONOFF=n==='frankraft'&&!OPFK.son; juego=n==='futbol'?crearFutbol11():n==='futauto'?crearFutAuto():n==='basquet'?crearBasquet():n==='penales'?crearPenales():n==='bolos'?crearBolos():n==='pesca'?crearPesca():n==='roba'?crearRoba():n==='mina'?crearMina():n==='rompe'?crearRompe():n==='parque'?crearParque():n==='backrooms'?crearBackrooms():n==='almacen'?crearAlmacen():n==='frankraft'?crearFrancraft(nivel===1):n==='laberinto'?crearLaberinto(nivel||0):n==='parkour'?crearParkour(nivel||0):(n==='royale'?crearRoyale():(n==='carrera'?crearCarrera(nivel||0):(n==='meteoritos'?crearMeteoritos():(n==='piso'?crearPiso():(n==='salva'?crearSalva(nivel||0):crearZombis())))));
  if(n==='carrera'){ pitch=0.32; yaw=juego.C[0].h+Math.PI; } tactilEl.style.display=esTactil()?'block':'none'; tactilEl.bF.style.display=(n==='zombis'||n==='royale')?'flex':'none'; tactilEl.bA.style.display=(n==='royale'||n==='zombis')?'flex':'none'; tactilEl.bA.textContent=n==='zombis'?'GRANADA':'ABRIR'; if(n==='mina'||n==='roba'){ tactilEl.bF.style.display='flex'; } if(n==='almacen'||n==='parque'||n==='rompe'||n==='mina'||n==='roba'){ tactilEl.bA.style.display='flex'; tactilEl.bA.textContent=n==='rompe'?'USAR / GOLPE':'USAR'; }
  if(n==='pesca'){ tactilEl.bA.style.display='flex'; tactilEl.bA.textContent='MENU'; } if(n==='futauto') tactilEl.bF.style.display='flex'; if(n==='futbol'){ tactilEl.bF.style.display='flex'; tactilEl.bA.style.display='flex'; tactilEl.bA.textContent='PASE'; } if(n==='frankraft'){ tactilEl.bF.style.display='flex'; tactilEl.bA.style.display='flex'; tactilEl.bA.textContent='PONER'; tactilEl.bG.style.display='flex'; tactilEl.bG.textContent='CRAFTEAR'; } else tactilEl.bG.textContent='GESTO'; tactilEl.bG.style.display=(n==='royale'||n==='frankraft')?'flex':'none'; if(n==='rompe'){ tactilEl.bG.style.display='flex'; tactilEl.bG.textContent='FLEXION'; } if(n==='roba'){ tactilEl.bG.style.display='flex'; tactilEl.bG.textContent='TRAMPA'; } if(n==='parque'){ tactilEl.bG.style.display='flex'; tactilEl.bG.textContent='CONSTRUIR'; } if(n==='futbol'){ tactilEl.bG.style.display='flex'; tactilEl.bG.textContent='CAMBIAR'; } if(n==='pesca'){ tactilEl.bG.style.display='flex'; tactilEl.bG.textContent='CAÑA'; tactilEl.bF.style.display='flex'; }
  miraEl.style.display=(n==='zombis'||n==='royale'||n==='frankraft')?'block':'none'; if(n==='salva') tactilEl.style.display='none'; vidaEl.style.display=(n==='zombis'||n==='royale')?'block':'none'; if(n==='carrera'){ tactilEl.bF.style.display='flex'; tactilEl.bF.textContent='ACELERAR'; } else tactilEl.bF.textContent=n==='frankraft'?'ROMPER':n==='mina'?'PICAR':n==='roba'?'BATE':n==='pesca'?'PESCAR':n==='futauto'?'TURBO':n==='futbol'?'PATEAR':'TIRAR'; try{ cv.focus(); }catch(e){} }
