function cerrar(){ if(juego&&juego.nombre==='roba'){ guardarRoba(juego); rbPanel(juego,null); } if(juego&&juego.nombre==='mina') guardarMina(juego); if(juego&&juego.nombre==='rompe') guardarRompe(juego); if(juego&&juego.nombre==='parque'){ guardarParque(juego); cerrarPanelPq(juego); } if(juego&&juego.nombre==='backrooms') pararBackrooms(juego); if(juego&&juego.nombre==='pesca'){ psPanel(juego,false); guardarPesca(juego); } if(juego&&juego.nombre==='almacen'){ guardarAlm(juego); cerrarPanelAlm(juego); } if(juego&&juego.nombre==='frankraft'){ fkGuardar(juego); cerrarCraft(juego); } abierto=false; cancelAnimationFrame(raf); caja.style.display='none'; window.removeEventListener('keydown',kd,true); window.removeEventListener('keyup',ku,true);
  try{ if(document.pointerLockElement) document.exitPointerLock(); }catch(e){} var m=monedas; monedas=0; if(alCerrar) alCerrar(m); }
window.Juegos3D={abrir:abrir,abierto:function(){ return abierto; },_t:{cam:function(){ return CAM; },empezar:empezar,juego:function(){return juego;},teclas:teclas,btn:btn,setYaw:function(a,b){ yaw=a; if(b!==undefined) pitch=b; },ganar:function(){ var g=juego; g.j.fase='suelo'; g.j.y=0; g.B.forEach(function(b){ b.vivo=false; b.mt=5; }); var b=g.B[0]; b.vivo=true; b.mt=0; b.fase='suelo'; b.y=0; b.x=g.j.x; b.z=g.j.z-5; danoR(g,b,999,g.j); }}};
